import "./App.css";
import { BrowserRouter as Router, Routes, Route, Link } from "react-router-dom";
import Home from "./pages/Home";
import CreatePost from "./pages/CreatePost";
import Login from "./pages/Login";
import TheoryList from "./pages/TheoryList";
import CreateTheory from "./pages/CreateTheory";
import { useState } from "react";
import { signOut } from "firebase/auth";
import { auth } from "./firebase-config";

function App() {
  const [isAuth, setIsAuth] = useState(localStorage.getItem("isAuth"));

  const signUserOut = () => {
    signOut(auth).then(() => {
      localStorage.clear();
      setIsAuth(false);
      window.location.pathname = "/login";
    });
  };

  return (
    <Router>
      <nav>
        <Link to="/"> На главную </Link>

        {!isAuth ? (
          <Link to="/login"> Войти </Link>
        ) : (
          <>
            <Link to="/theory"> Темы </Link>
            <Link to="/createtheory"> Создать тему</Link>
            <Link to="/createpost"> Создать задачу </Link>
            <button onClick={signUserOut}> Выйти</button>
          </>


        )}
      </nav>
      <Routes>
        <Route path="/" element={<Home isAuth={isAuth} />} />
        <Route path="/createpost" element={<CreatePost isAuth={isAuth} />} />
        <Route path="/login" element={<Login setIsAuth={setIsAuth} />} />
        <Route path="/theory" element={<TheoryList isAuth={isAuth} />} />
        <Route path="/createtheory" element={<CreateTheory isAuth={isAuth} />} />
      </Routes>
    </Router>
  );
}

export default App;
